package io.atlas.modules.crates.menu;
import io.atlas.modules.crates.service.CrateService;
import io.atlas.modules.crates.service.CrateService.*;
import net.minecraft.world.inventory.*;import net.minecraft.world.entity.player.*;import net.minecraft.world.item.*;import net.minecraft.world.SimpleContainer;import net.minecraft.core.component.DataComponents;import net.minecraft.world.item.component.ItemLore;import net.minecraft.network.chat.Component;import net.minecraft.server.level.ServerPlayer;import java.util.*;
public final class CrateMenu extends ChestMenu {
 private final CrateService service;private final Pool pool;private final int page;private final boolean rolling;private final SimpleContainer contents;private boolean finished;
 public CrateMenu(int id,Inventory inv,CrateService service,Pool pool,int page,boolean rolling){this(id,inv,service,pool,page,rolling,new SimpleContainer(54));}
 private CrateMenu(int id,Inventory inv,CrateService service,Pool pool,int page,boolean rolling,SimpleContainer contents){super(MenuType.GENERIC_9x6,id,inv,contents,6);this.service=service;this.pool=pool;this.page=Math.max(0,Math.min(page,(pool.entries().size()-1)/45));this.rolling=rolling;this.contents=contents;render();}
 public boolean rolling(){return rolling;}
 private ItemStack icon(ItemStack stack,String name,String... lore){stack=stack.copy();stack.set(DataComponents.CUSTOM_NAME,Component.literal(name));stack.set(DataComponents.LORE,new ItemLore(Arrays.stream(lore).map(s->(Component)Component.literal(s)).toList()));return stack;}
 private ItemStack prize(Entry e){double total=pool.entries().stream().mapToDouble(Entry::weight).sum();return icon(e.icon(),"§b"+e.name()+(e.shiny()?" §6★ Shiny":" §fNormal"),"§7Nível 70 • 1 CHAVE VIRTUAL","§7Chance: "+String.format(Locale.forLanguageTag("pt-BR"),"%.3f%%",e.weight()*100/total),"§7Entrega na equipe ou PC");}
 private void render(){contents.clearContent();if(rolling){animate(0);return;}for(int i=0;i<45;i++){int n=page*45+i;if(n<pool.entries().size())contents.setItem(i,prize(pool.entries().get(n)));}if(page>0)contents.setItem(45,icon(new ItemStack(Items.ARROW),"§ePágina anterior"));contents.setItem(49,icon(new ItemStack(Items.BOOK),"§61 CHAVE VIRTUAL • Página "+(page+1),"§7Cada prêmio possui o mesmo peso.","§7Normal: 50% • Shiny: 50%","§7Na caixa: esquerdo vê • direito sorteia","§7Consulte seu saldo em /compras."));if((page+1)*45<pool.entries().size())contents.setItem(53,icon(new ItemStack(Items.ARROW),"§ePróxima página"));broadcastChanges();}
 public void stopOn(String properties){showResult(properties,false);}
 public void reveal(String properties){showResult(properties,true);}
 private void showResult(String properties,boolean delivered){finished=true;contents.clearContent();var entry=pool.entries().stream().filter(e->e.properties().equals(properties)).findFirst().orElseThrow();for(int i=0;i<54;i++)contents.setItem(i,icon(new ItemStack(Items.BLACK_STAINED_GLASS_PANE)," "));contents.setItem(13,icon(new ItemStack(Items.YELLOW_STAINED_GLASS_PANE),"§6▼ SEU PRÊMIO ▼"));contents.setItem(31,icon(new ItemStack(Items.YELLOW_STAINED_GLASS_PANE),"§6▲ SEU PRÊMIO ▲"));contents.setItem(22,prize(entry));contents.setItem(49,icon(new ItemStack(delivered?Items.EMERALD:Items.CLOCK),delivered?"§aPrêmio entregue!":"§6★ Pokémon sorteado!",delivered?"§7Consulte sua equipe ou PC.":"§ePreparando sua entrega…","§7ESC para fechar."));broadcastChanges();}
 public void animate(int frame){if(finished)return;for(int i=0;i<54;i++)contents.setItem(i,icon(new ItemStack(Items.BLACK_STAINED_GLASS_PANE)," "));for(int i=0;i<9;i++)contents.setItem(18+i,prize(pool.entries().get((frame+i)%pool.entries().size())));contents.setItem(13,icon(new ItemStack(Items.LIME_STAINED_GLASS_PANE),"§a▼ Prêmio ▼"));contents.setItem(31,icon(new ItemStack(Items.LIME_STAINED_GLASS_PANE),"§a▲ Prêmio ▲"));contents.setItem(49,icon(new ItemStack(Items.CLOCK),"§eSorteando…","§7Fechar a janela não cancela o prêmio."));broadcastChanges();}
 @Override public void clicked(int slot,int button,ClickType type,Player player){if(rolling||!(player instanceof ServerPlayer p)||type!=ClickType.PICKUP||button!=0)return;if(slot==45&&page>0)service.preview(p,pool,page-1);else if(slot==53&&(page+1)*45<pool.entries().size())service.preview(p,pool,page+1);}
 @Override public ItemStack quickMoveStack(Player p,int slot){return ItemStack.EMPTY;}
 @Override public boolean stillValid(Player p){var b=pool.box();return p instanceof ServerPlayer sp&&service.allowed(sp)&&p.level().dimension().location().toString().equals(b.dimension())&&p.distanceToSqr(b.x()+.5,b.y()+.5,b.z()+.5)<=64;}
}
